static constexpr size_t NUM_ICONS = sizeof(ICON_ENTRIES) / sizeof(ICON_ENTRIES[0]);

// Linear search for an icon name; returns fallback (cog) if not found
inline const char* find_icon(const char* name) {
  // Keep serialized icon names from releases that used the typographic
  // "Wi-Fi" spelling working after the visible labels moved to "Wifi".
  static const IconEntry legacy_icon_aliases[] = {
      {"Wi-Fi Startup",              "\U000F05A9"},
      {"Wi-Fi",                      "\U000F0928"},
      {"Wi-Fi Strength Outline",     "\U000F092F"},
      {"Wi-Fi Strength 1",           "\U000F091F"},
      {"Wi-Fi Strength 2",           "\U000F0922"},
      {"Wi-Fi Strength 3",           "\U000F0925"},
      {"Wi-Fi Strength Off Outline", "\U000F092E"},
  };
  for (const IconEntry &alias : legacy_icon_aliases) {
    if (std::strcmp(alias.name, name) == 0) return alias.glyph;
  }
  for (size_t i = 0; i < NUM_ICONS; i++) {
    if (std::strcmp(ICON_ENTRIES[i].name, name) == 0) {
      return ICON_ENTRIES[i].glyph;
    }
  }
  return "\U000F0493";
}

// Return the default icon for a HA entity domain (e.g. "light" → Lightbulb)
inline const char* domain_default_icon(const std::string &domain) {
  // --- GENERATED:DOMAIN_ICONS START ---
  if (domain == "switch")                     return "\U000F06A5";  // Power Plug
  if (domain == "fan")                        return "\U000F0210";  // Fan
  if (domain == "lock")                       return "\U000F033E";  // Lock
  if (domain == "media_player")               return "\U000F04C3";  // Speaker
  if (domain == "button")                     return "\U000F0741";  // Gesture Tap
  // --- GENERATED:DOMAIN_ICONS END ---
  return "\U000F0493";
}

// Check if a HA entity state string represents "on" (covers, locks, media, etc.)
inline bool is_entity_on(const std::string &state) {
  return state == "on" ||
         state == "open" ||
         state == "opening" ||
         state == "closing" ||
         state == "playing" ||
         state == "home" ||
         state == "unlocked";
}
